BEGIN TRANSACTION;
CREATE TABLE "code_sessions" (session_id VARCHAR NOT NULL, session_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, session_data JSON, agent_data JSON, team_data JSON, workflow_data JSON, metadata JSON, summary JSON, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (session_id));
INSERT INTO "code_sessions" VALUES('session','agent','code',NULL,NULL,NULL,'{"session_state": {}}',NULL,NULL,NULL,'null',NULL,1750000000,1750000000);
CREATE TABLE "code_sessions_removed_runs" (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "code_sessions"(session_id) ON DELETE CASCADE);
CREATE TABLE "code_sessions_runs" (run_id VARCHAR NOT NULL, session_id VARCHAR NOT NULL, run_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, parent_run_id VARCHAR, status VARCHAR, run_index BIGINT, run_data JSON NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (run_id), FOREIGN KEY(session_id) REFERENCES "code_sessions" (session_id) ON DELETE CASCADE);
INSERT INTO "code_sessions_runs" VALUES('r0','session','agent','code',NULL,NULL,NULL,NULL,'COMPLETED',0,'{"run_id": "r0", "agent_id": "code", "session_id": "session", "content": "answer r0", "created_at": 1750000000, "status": "COMPLETED", "messages": [{"id": "r0.u", "content": "question r0", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$r0", "matrix_seen_event_ids": ["$r0"]}}',1750000000,1750000000);
INSERT INTO "code_sessions_runs" VALUES('live','session','agent','code',NULL,NULL,NULL,NULL,'PAUSED',2,'{"run_id": "live", "agent_id": "code", "session_id": "session", "content": "answer live", "created_at": 1750000000, "status": "PAUSED", "messages": [{"id": "live.u", "content": "question live", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$live", "matrix_seen_event_ids": ["$live"]}}',1750000000,1750000000);
CREATE TABLE "code_sessions_summaries" (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "code_sessions"(session_id) ON DELETE CASCADE, scope_key TEXT NOT NULL, after_run_index INTEGER NOT NULL, summary TEXT, summary_model TEXT, event_ids TEXT NOT NULL DEFAULT '[]', seen_event_ids TEXT NOT NULL DEFAULT '[]', legacy INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, segment_run_id TEXT, segment TEXT);
INSERT INTO "code_sessions_summaries" VALUES(1,'session','agent:code',-1,'fold of live','summary-model','["$live"]','[]',0,1750000000,'live','{"metadata": {"matrix_event_id": "$live"}, "messages": [{"id": "live.b0", "from_history": false, "stop_after_tool_call": false, "role": "assistant", "tool_calls": [{"id": "live.c0", "type": "function", "function": {"name": "probe", "arguments": "{}"}}], "created_at": 1750000000}], "tools": [{"tool_call_id": "execution-only", "tool_name": "probe", "tool_args": null, "tool_call_error": null, "result": null, "metrics": null, "child_run_id": null, "stop_after_tool_call": false, "created_at": 1750000000, "requires_confirmation": null, "confirmed": null, "confirmation_note": null, "external_execution_required": null, "external_execution_silent": null, "approval_type": null}], "member_responses": []}');
CREATE TABLE "code_sessions_usage" (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "code_sessions"(session_id) ON DELETE CASCADE, run_id TEXT, usage_data TEXT, UNIQUE(session_id, run_id));
CREATE INDEX "idx_code_sessions_session_type" ON "code_sessions" (session_type);
CREATE INDEX "idx_code_sessions_created_at" ON "code_sessions" (created_at);
CREATE INDEX "idx_code_sessions_runs_session_id" ON "code_sessions_runs" (session_id);
CREATE INDEX "idx_code_sessions_runs_run_type" ON "code_sessions_runs" (run_type);
CREATE INDEX "idx_code_sessions_runs_agent_id" ON "code_sessions_runs" (agent_id);
CREATE INDEX "idx_code_sessions_runs_team_id" ON "code_sessions_runs" (team_id);
CREATE INDEX "idx_code_sessions_runs_workflow_id" ON "code_sessions_runs" (workflow_id);
CREATE INDEX "idx_code_sessions_runs_user_id" ON "code_sessions_runs" (user_id);
CREATE INDEX "idx_code_sessions_runs_status" ON "code_sessions_runs" (status);
CREATE INDEX "idx_code_sessions_runs_created_at" ON "code_sessions_runs" (created_at);
CREATE INDEX "idx_code_sessions_runs_session_id_run_index" ON "code_sessions_runs" (session_id, run_index);
CREATE INDEX "code_sessions_summaries_scope" ON "code_sessions_summaries" (session_id, scope_key, id);
CREATE INDEX "code_sessions_removed_runs_session" ON "code_sessions_removed_runs" (session_id);
COMMIT;
